package com.playertags;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("playertags")
public interface PlayerTagsConfig extends Config
{
    @ConfigItem(
        keyName = "showOwnTag",
        name = "Show my tag",
        description = "Allow your custom information to appear when someone hovers over you",
        position = 0
    )
    default boolean showOwnTag()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showOwnTagLocally",
            name = "Show my own tag locally",
            description = "Only controls whether you see your own tag",
            position = 1
    )
    default boolean showOwnTagLocally()
    {
        return false;
    }

    @ConfigItem(
        keyName = "ownTag",
        name = "My custom tag",
        description = "Your custom tag text",
        position = 2
    )
    default String ownTag()
    {
        return "";
    }

    @ConfigItem(
        keyName = "ownPronouns",
        name = "My pronouns",
        description = "Your pronouns (for example, they/them)",
        position = 3
    )
    default String ownPronouns()
    {
        return "";
    }

    @ConfigItem(
        keyName = "showOtherTags",
        name = "Show other players",
        description = "Show information for players with a local override",
        position = 4
    )
    default boolean showOtherTags()
    {
        return true;
    }

    @ConfigItem(
        keyName = "localOverrides",
        name = "Local player overrides",
        description = "One player per line: PlayerName=Custom tag|pronouns (pronouns optional)",
        position = 5
    )
    default String localOverrides()
    {
        return "";
    }

    @ConfigItem(
        keyName = "hiddenPlayers",
        name = "Hidden players",
        description = "Comma-separated player names whose information should be hidden",
        position = 6
    )
    default String hiddenPlayers()
    {
        return "";
    }

    @ConfigItem(
        keyName = "tagColor",
        name = "Text colour",
        description = "Colour used for the custom tag and pronouns in the hover box",
        position = 7
    )
    default Color tagColor()
    {
        return new Color(220, 205, 255);
    }

    @Range(min = 10, max = 24)
    @ConfigItem(
        keyName = "fontSize",
        name = "Text size",
        description = "Text size inside the hover box",
        position = 8
    )
    default int fontSize()
    {
        return 12;
    }
}

package com.playertags;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws a compact information box when the mouse is over a tagged player model. */
public class PlayerTagsOverlay extends Overlay
{
    private static final int BOX_PADDING = 9;
    private static final int CURSOR_OFFSET = 16;
    private static final Color BACKGROUND = new Color(28, 25, 35, 238);
    private static final Color BORDER = new Color(155, 130, 190, 230);
    private static final Color LABEL = new Color(190, 185, 200);

    private final Client client;
    private final PlayerTagsPlugin plugin;

    @Inject
    private PlayerTagsOverlay(Client client, PlayerTagsPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null)
        {
            return null;
        }

        Player hoveredPlayer = findHoveredPlayer(mouse);
        if (hoveredPlayer == null)
        {
            return null;
        }

        PlayerTagsPlugin.PlayerInfo info = plugin.getPlayerInfo(hoveredPlayer);
        if (info == null)
        {
            return null;
        }

        drawTooltip(graphics, mouse, info);
        return null;
    }

    private Player findHoveredPlayer(Point mouse)
    {
        // Iterate backwards so the last-drawn/foreground actor wins if model
        // hulls overlap on screen.
        java.util.List<Player> players = client.getPlayers();
        for (int i = players.size() - 1; i >= 0; i--)
        {
            Player player = players.get(i);
            if (player == null || player.getName() == null)
            {
                continue;
            }

            if (player == client.getLocalPlayer()
                    && !plugin.getConfig().showOwnTagLocally())
            {
                continue;
            }

            Shape hull = player.getConvexHull();
            if (hull != null && hull.contains(mouse.getX(), mouse.getY()))
            {
                return player;
            }
        }
        return null;
    }

    private void drawTooltip(Graphics2D parent, Point mouse, PlayerTagsPlugin.PlayerInfo info)
    {
        Graphics2D graphics = (Graphics2D) parent.create();
        try
        {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            Font oldFont = graphics.getFont();
            Font valueFont = oldFont.deriveFont(Font.BOLD, (float) plugin.getConfig().fontSize());
            Font labelFont = oldFont.deriveFont(Font.PLAIN, Math.max(9f, plugin.getConfig().fontSize() - 2f));

            String tag = info.getTag();
            String pronouns = info.getPronouns();
            FontMetrics valueMetrics = graphics.getFontMetrics(valueFont);
            FontMetrics labelMetrics = graphics.getFontMetrics(labelFont);

            int valueColumnWidth = labelMetrics.stringWidth("PRONOUNS") + 8;
            int widestValue = Math.max(
                tag.isEmpty() ? 0 : valueMetrics.stringWidth(tag),
                pronouns.isEmpty() ? 0 : valueMetrics.stringWidth(pronouns));
            int contentWidth = valueColumnWidth + widestValue;

            int lineHeight = Math.max(valueMetrics.getHeight(), labelMetrics.getHeight());
            int rows = (tag.isEmpty() ? 0 : 1) + (pronouns.isEmpty() ? 0 : 1);
            int boxWidth = contentWidth + BOX_PADDING * 2;
            int boxHeight = rows * lineHeight + BOX_PADDING * 2 + (rows > 1 ? 3 : 0);

            int x = mouse.getX() + CURSOR_OFFSET;
            int y = mouse.getY() + CURSOR_OFFSET;
            int canvasWidth = client.getCanvasWidth();
            int canvasHeight = client.getCanvasHeight();
            if (x + boxWidth > canvasWidth - 4)
            {
                x = mouse.getX() - boxWidth - CURSOR_OFFSET;
            }
            if (y + boxHeight > canvasHeight - 4)
            {
                y = mouse.getY() - boxHeight - CURSOR_OFFSET;
            }
            x = Math.max(4, x);
            y = Math.max(4, y);

            graphics.setColor(BACKGROUND);
            graphics.fillRoundRect(x, y, boxWidth, boxHeight, 9, 9);
            graphics.setColor(BORDER);
            graphics.drawRoundRect(x, y, boxWidth, boxHeight, 9, 9);

            int baseline = y + BOX_PADDING + valueMetrics.getAscent();
            int labelX = x + BOX_PADDING;
            int valueX = labelX + labelMetrics.stringWidth("PRONOUNS") + 8;

            if (!tag.isEmpty())
            {
                graphics.setFont(labelFont);
                graphics.setColor(LABEL);
                graphics.drawString("TAG", labelX, baseline - (valueMetrics.getAscent() - labelMetrics.getAscent()) / 2);
                graphics.setFont(valueFont);
                graphics.setColor(plugin.getConfig().tagColor());
                graphics.drawString(tag, valueX, baseline);
                baseline += lineHeight + 3;
            }

            if (!pronouns.isEmpty())
            {
                graphics.setFont(labelFont);
                graphics.setColor(LABEL);
                graphics.drawString("PRONOUNS", labelX, baseline - (valueMetrics.getAscent() - labelMetrics.getAscent()) / 2);
                graphics.setFont(valueFont);
                graphics.setColor(plugin.getConfig().tagColor());
                graphics.drawString(pronouns, valueX, baseline);
            }
        }
        finally
        {
            graphics.dispose();
        }
    }
}

package com.playertags;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Player Tags",
    description = "Shows custom player tags and pronouns in a hover tooltip",
    tags = {"players", "custom", "tags", "pronouns", "tooltip"}
)
public class PlayerTagsPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private PlayerTagsConfig config;

    @Inject
    private PlayerTagsOverlay overlay;

    @Provides
    PlayerTagsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PlayerTagsConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
    }

    PlayerInfo getPlayerInfo(Player player)
    {
        if (player == null || player.getName() == null)
        {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();
        String playerName = normalize(player.getName());
        String localName = localPlayer == null ? "" : normalize(localPlayer.getName());

        if (playerName.equals(localName))
        {
            if (!config.showOwnTag())
            {
                return null;
            }
            return makeInfo(config.ownTag(), config.ownPronouns());
        }

        if (!config.showOtherTags() || isHidden(playerName))
        {
            return null;
        }

        return findOverride(playerName);
    }

    private PlayerInfo findOverride(String normalizedName)
    {
        String mappings = config.localOverrides();
        if (mappings == null || mappings.trim().isEmpty())
        {
            return null;
        }

        for (String line : mappings.split("\\R"))
        {
            int separator = line.indexOf('=');
            if (separator <= 0)
            {
                continue;
            }

            String name = normalize(line.substring(0, separator).trim());
            if (!normalizedName.equals(name))
            {
                continue;
            }

            String[] values = line.substring(separator + 1).split("\\|", 2);
            String tag = values.length > 0 ? values[0] : "";
            String pronouns = values.length > 1 ? values[1] : "";
            return makeInfo(tag, pronouns);
        }
        return null;
    }

    private boolean isHidden(String normalizedName)
    {
        String hidden = config.hiddenPlayers();
        if (hidden == null)
        {
            return false;
        }

        for (String name : hidden.split(","))
        {
            if (normalizedName.equals(normalize(name.trim())))
            {
                return true;
            }
        }
        return false;
    }

    private static PlayerInfo makeInfo(String tag, String pronouns)
    {
        String cleanTag = cleanText(tag);
        String cleanPronouns = cleanText(pronouns);
        if (cleanTag.isEmpty() && cleanPronouns.isEmpty())
        {
            return null;
        }
        return new PlayerInfo(cleanTag, cleanPronouns);
    }

    private static String cleanText(String text)
    {
        if (text == null)
        {
            return "";
        }
        String cleaned = text.replaceAll("[\\r\\n\\t]", " ").trim();
        return cleaned.length() > 32 ? cleaned.substring(0, 32) : cleaned;
    }

    private static String normalize(String name)
    {
        return name == null ? "" : name.replace('\u00A0', ' ').trim().toLowerCase();
    }

    PlayerTagsConfig getConfig()
    {
        return config;
    }

    static final class PlayerInfo
    {
        private final String tag;
        private final String pronouns;

        private PlayerInfo(String tag, String pronouns)
        {
            this.tag = tag;
            this.pronouns = pronouns;
        }

        String getTag()
        {
            return tag;
        }

        String getPronouns()
        {
            return pronouns;
        }
    }
}

package com.playertags;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PlayerTagsTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(PlayerTagsPlugin.class);
        RuneLite.main(args);
    }
}
